// Webhook body -> one item per chunk, with the temporal fields the Sort node needs.
// Expected POST body:
//   { "batch_id": "...", "classifier_version": "...", "items":
//       [ { "record_id": "...", "chunk_id": "...", "chunk_text": "...",
//           "occurred_at_epoch_ms": 1756070000000 }, ... ] }
const body = $input.first().json.body || $input.first().json || {};
const items = body.items || [];
if (!Array.isArray(items) || items.length === 0) {
  throw new Error('classify-batch: body.items must be a non-empty array of chunk records');
}
const receivedAt = Date.now();
const batchId = body.batch_id || ('batch-' + receivedAt);
// PLACEHOLDER: the classifier version travels with every row (versioned-drafts rule).
const classifierVersion = body.classifier_version || '{{CLASSIFIER_VERSION}}';

return items.map((it, i) => {
  if (!it.record_id || !it.chunk_id) {
    throw new Error('classify-batch: every item needs record_id and chunk_id (IDs only - never raw evidence)');
  }
  const occurred = Number(it.occurred_at_epoch_ms || 0);
  return { json: {
    batch_id: batchId,
    batch_index: i,
    record_id: it.record_id,
    chunk_id: it.chunk_id,
    chunk_text: String(it.chunk_text || ''),
    // TEMPORAL MANDATE: epoch-numeric so the Sort node compares numbers, plus ISO for humans.
    occurred_at_epoch_ms: occurred,
    occurred_at_iso: occurred ? new Date(occurred).toISOString() : null,
    received_at_epoch_ms: receivedAt,
    received_at_iso: new Date(receivedAt).toISOString(),
    classifier_version: classifierVersion,
    activity_name: 'n8n.classify.batch',
  }};
});

