parameters.jsCode:
// Collect every looped item into ONE response payload for the caller (Temporal activity result).
const rows = $input.all().map(i => i.json);
const now = Date.now();
return [{ json: {
  activity_name: 'n8n.classify.batch',
  status: 'completed',
  batch_id: rows.length ? rows[0].batch_id : null,
  classifier_version: rows.length ? rows[0].classifier_version : null,
  count: rows.length,
  // rows that came back without labels went through the repair chain and still failed -
  // they are reported, never silently dropped.
  unlabeled_count: rows.filter(r => !r.labels).length,
  completed_at_epoch_ms: now,
  completed_at_iso: new Date(now).toISOString(),
  results: rows,
}}];
